  fireEvent.click(within(dialog).getByRole("button", { name: "Apply" }));
  await waitFor(() =>
    expect(
      screen.queryByRole("dialog", { name: "Global Broadcast Time Override" }),
    ).toBeNull(),
  );
  expect(command("Set Global Broadcast Time Override")).toHaveAttribute(
