  fetchSongsPage.mockResolvedValue(
    pageOf(
      [
        song(1, {
          coverUrl: "https://media.test/1.jpg",
          intro: { instantId: 5, instant: { name: "Hello segue" } },
        }),
        song(2, { artist: "", title: "", durationMs: null, enabled: false }),
        song(3, { artist: "  Solo  ", title: " ", durationMs: 400 }),
      ],
      {
        total: 3,
        catalogTotal: 10,
        catalogEnabled: 8,
